src/strategy/actions/BankAction.cpp::Exe.raw:
{
  "summary": "Executes a bank action by locating the nearest banker NPC and delegating the transaction to them.",
  "overview": "This function iterates through a list of nearby NPCs to identify the closest unit with the banker flag. Once a valid banker is found, it delegates the actual banking operation to ExecuteBank, passing the transaction text and the target NPC's GUID. If no suitable banker exists within range, an error message is logged and the function returns false.",
  "params": [
    {
      "name": "event",
      "desc": "The event object containing the action parameters, specifically the transaction text."
    }
  ],
  "returns": "bool",
  "side_effects": "None",
  "notes": "Relies on botAI->GetUnit and UNIT_NPC_FLAG_BANKER for NPC identification; callers must ensure the event contains a valid 'text' parameter."
}

{
  "summary": "Executes bank-related commands by parsing text input to either list items, withdraw specific items, or deposit items into the bank.",
  "overview": "This function processes a string command to interact with a unit's bank. If the text is empty or contains only '?', it lists all items in the bank and returns true. For other inputs, it checks the first character: a '-' prefix triggers item withdrawal by parsing the remaining text against items currently in the bank, while any other character attempts to deposit items found in bags matching the text.",
  "params": [
    {
      "name": "text",
      "desc": "The command string; empty or '?' lists items, '-' prefixed strings withdraw items, otherwise deposits items from bags."
