src/strategy/actions/BattleGroundJoinAct.raw:
{
  "summary": "Gathers a team of players from an existing arena team, creates a new group for them, and teleports all members to the bot's location.",
  "overview": "This function attempts to assemble a battle-ready team by iterating through members of a specified arena type and filtering out those who are offline, in combat, or do not meet specific criteria. If a sufficient number of valid players are found, it creates a new group, teleports the members to the bot's position, and returns true; otherwise, it logs an informational message and returns false.",
  "params": [
    {
      "name": "type",
      "desc": "The ArenaType enum value defining the required team size and type for the gathering."
    }
  ],
  "returns": "bool",
  "side_effects": "Network, Global State",
  "notes": "Calls ObjectAccessor::FindConnectedPlayer to locate players; modifies global arena and group manager state by potentially disbanding existing groups and creating new ones. Edge case: Requires at least one online player in the specified arena team."
}

{
  "summary": "Determines whether a bot can join a specific battleground queue and bracket based on its level, current queue status, and access rights.",
  "overview": "This function evaluates if a bot is eligible to enter a Battleground by first verifying it is not already in the specified queue type. It then checks the bot's level against the battleground template to ensure it meets the minimum access requirements for that specific battleground. Finally, it calculates the required bracket ID based on the map and the bot's level, comparing it against the provided bracketId to confirm a match.",
  "params": [
    {
      "name": "queueTypeId",
      "desc": "The type of battleground queue the bot is attempting to join."
    },
    {
      "name": "bracketId",
      "desc": "The specific bracket ID the bot is trying to enter within the battleground."
    }
  ],
  "returns": "bool",
  "side_effects": "None",
  "notes": "Returns false if the bot is already in a queue of this type, lacks level access for the battleground, or the calculated bracket does not match the requested bracketId."
}

{
  "summary": "Determines whether a bot should join a specific battleground queue and bracket based on team leadership, arena type requirements, and available slots.",
  "overview": "This function evaluates if a bot is eligible to enter a Battleground instance by first verifying the existence of the template and confirming the bot is a group leader. It then calculates capacity limits for both standard and rated arenas, checking against global counters for bots and players in the specific queue and bracket. Finally, it assesses availability based on team affiliation (Alliance or Horde) for non-arena battlegrounds.",
  "params": [
    {
      "name": "queueTypeId",
      "desc": "The unique identifier for the Battleground queue type."
    },
    {
      "name": "bracketId",
      "desc": "The specific bracket or instance ID within the queue."
    }
  ],
  "returns": "bool",
  "side_effects": "None",
  "notes": "Reads from global managers (BattlegroundMgr, RandomShadowMgr, ArenaTeamMgr) and modifies internal counters in sRandomShadowMgr for rated arenas."
}

{
  "summary": "Attempts to queue a bot character into the specified battleground or arena type, returning false if prerequisites are not met.",
  "overview": "This function validates that the bot is present in the world and not already in a battleground before attempting to join a queue. It retrieves the specific battleground template based on the provided type ID, checks for level-based access requirements, and verifies the bot is not already queued for that specific battleground type. The function then calculates team sizes and bracket IDs, handles special logic for arena types including rated status and group composition, and finally sends the appropriate network packet to the Battlemaster server.",
  "params": [
    {
      "name": "type",
      "desc": "The ID of the battleground or arena type the bot should attempt to join."
    }
  ],
  "returns": "bool",
  "side_effects": "Network (sends CMSG_BATTLEMASTER_JOIN packet for BGs, handles arena join for Arenas), Global State (increments bot counts in sRandomShadowMgr BattlegroundData)",
  "notes": "Returns false if the bot is not in world, already in a battleground, or already queued for this type. Requires valid Battlemaster unit presence for Arena types."
}

{
  "summary": "Processes a Shadow AI bot's departure from a Battleground or Arena by updating its strategy states, logging the event, and sending a client-side leave packet.",
  "overview": "This function handles the logic for a Shadow AI bot leaving a Battleground or Arena. It first verifies that the bot is currently in a valid battleground context before proceeding. The core of the function involves iterating through specific strategy tags (such as warsong, arathi, eye, and general battleground/arena states) to transition them from combat to non-combat modes, ensuring the bot's AI behavior reflects its departure.",
  "params": [
    {
      "name": "botAI",
      "desc": "Pointer to the Shadow AI object representing the bot that is leaving."
    }
  ],
  "returns": "bool",
  "side_effects": "I/O, network, global state",
  "notes": "The function logs an informational message and sends a CMSG_LEAVE_BATTLEFIELD packet to the client. It resets specific AI context values for battleground type, role, arena type, and position data upon completion."
}

{
  "summary": "Processes incoming battle ground join events for bots, parsing status data and executing logic to handle queue waiting, forced joins, or in-progress battles.",
  "overview": "This function parses the event packet to extract battle ground parameters such as instance ID, map ID, level requirements, and current status. It determines the specific battleground type and arena configuration based on the bot's level and the received data, then logs relevant information for debugging. The core logic handles different statuses like waiting in a queue or an active battle, triggering actions like forced joins or automatic removal if conditions are met.",
  "params": [
    {
      "name": "event",
      "desc": "The Event object containing the packet data to be parsed and processed."
    }
  ],
  "returns": "bool",
  "side_effects": "Network (queues packets), Global State (accesses BattlegroundMgr, RandomShadowMgr, BotAI), Logging",
  "notes": "Calls LeaveBG(botAI) if TIME_TO_AUTOREMOVE is received; handles forced joins via CMSG_BATTLEFIELD_PORT packet; relies on global managers for queue and battleground data."
}

src/strategy/actions/BattleGroundTactics.raw:
{
  "summary": "Handles console commands for the Shadow system by validating configuration and session state before delegating to a private handler.",
  "overview": "This function acts as a public entry point for Shadow-related console commands, first checking if the Shadow AI configuration is enabled. It then verifies that the handler has an active WorldSession, returning early with error messages if either condition fails. Finally, it delegates the actual command processing to HandleConsoleCommandPrivate and returns true upon completion.",
  "params": [
    {
      "name": "handler",
      "desc": "Pointer to the ChatHandler instance that received the command."
    },
    {
      "name": "args",
      "desc": "The raw string argument provided by the user in the console command."
    }
  ],
  "returns": "bool",
  "side_effects": "I/O (PSendSysMessage), global state (sShadowAIConfig)",
  "notes": "Returns true on success or failure; checks for disabled Shadow system and missing active session before processing."
}

{
  "summary": "Executes GM-only console commands to summon temporary battlebot waypoints at specific battleground locations.",
  "overview": "This function processes private console arguments for game masters within a battleground context, allowing them to visualize bot paths or specific entities. It validates the user's security level and current battleground state before parsing commands like 'showpath', 'showcreature', or 'showobject'. Upon successful execution, it spawns temporary creatures at calculated coordinates to represent the requested data.",
  "params": [
    {
      "name": "session",
      "desc": "Pointer to the WorldSession object containing player and battleground context."
    },
    {
      "name": "args",
      "desc": "String containing the command name followed by optional parameters (e.g., 'showpath=all' or 'showcreature=0')."
    }
  ],
  "returns": "std::string const",
  "side_effects": "Network, global state",
  "notes": "Spawns temporary creatures (GUID 15631) with a 15-second despawn timer; requires GM security level and active battleground membership."
}

{
  "summary": "Retrieves the pre-configured battle strategy for a specific team within a given battleground instance.",
  "overview": "This function acts as a lookup utility that maps a battleground's unique instance ID to its stored strategy configuration. It first checks if a valid strategy entry exists for the provided battleground; if not, it defaults to returning zero. Upon finding a match, it selects either the alliance or horde strategy based on the team identifier passed in.",
  "params": [
    {
      "name": "bg",
      "desc": "Pointer to the Battleground object containing the instance ID used for strategy lookup."
    },
    {
      "name": "teamId",
      "desc": "The team identifier (TEAM_ALLIANCE or TEAM_HORDE) determining which specific strategy variant to return."
    }
  ],
  "returns": "uint8",
  "side_effects": "None",
  "notes": "Returns 0 if the battleground instance ID is not found in the global bgStrategies map. Callers should verify the returned value before applying it to bot behavior logic."
}

{
  "summary": "Moves the bot to a designated waiting position on the current battleground based on team affiliation and role.",
  "overview": "This function attempts to relocate the bot to a specific coordinate within its active battleground, utilizing predefined position constants for various battle types. It first validates that the bot has an associated battleground and checks if the force flag is set or if the battleground status allows joining; otherwise, it returns false immediately. The logic then branches based on the battleground type (such as WS, AB, AV, IC) to determine the appropriate target location, applying random offsets within a defined radius for realism.",
  "params": [
    {
      "name": "force",
      "desc": "If true, allows movement regardless of the battleground's current status; if false, movement only occurs if the battleground is in STATUS_WAIT_JOIN."
    }
  ],
  "returns": "bool",
  "side_effects": "Network (MoveTo), Global State (bot position update)",
  "notes": "The function relies on context values for role assignment and uses hardcoded position constants specific to different battleground maps. It handles multiple battle types including Waiting Spots, Alliance/Battlefield variants, and Ice Cavern configurations."
}

{
  "summary": "Selects a battlefield objective for the bot based on strategy, role, and current game state.",
  "overview": "This function determines the target objective for a bot within an Active Warfare battleground by evaluating team roles, enemy strategies, and specific node conditions. It prioritizes mine capture or snowfall defense objectives if available, falling back to targeting nearby enemies when no other objective is set. The selection logic dynamically adjusts based on whether the bot is in offensive or defensive mode and incorporates random chance factors for role switching.",
  "params": [
    {
      "name": "reset",
      "desc": "If true, forces the function to ignore existing position data and re-evaluate objectives from scratch; if false, it only selects a new objective if none currently exists."
    }
  ],
  "returns": "bool",
  "side_effects": "None",
  "notes": "The function relies on external context values for position maps and bot roles. It performs random number generation (urand) to determine mine capture targets, role switching chances, and fallback enemy targeting."
}

{
  "summary": "Moves the bot toward the objective position on the current battleground, optionally ignoring distance checks.",
  "overview": "This function retrieves the objective coordinates from the game context and attempts to move the bot there. It first validates that the bot is on a valid battleground and adjusts the battleground type if necessary for specific modes like Ice Caverns. The logic then checks if the bot is already locked inside a keep or if the distance to the objective exceeds a threshold, returning false if the latter condition is met when ignoreDist is false.",
  "params": [
    {
      "name": "ignoreDist",
      "desc": "If true, skips the distance check and proceeds to move toward the objective regardless of range."
    }
  ],
  "returns": "bool",
  "side_effects": "Network (MoveNear), Global State (resetObjective)",
  "notes": "Calls selectObjective() if position is unset; resets objective if bot reaches within 4.0f units."
}

{
  "summary": "Selects the optimal path from a provided list of BattleBotPath objects to reach the current battleground objective based on distance and reverse-path constraints.",
  "overview": "This function evaluates a collection of battle paths to determine which one best leads to the active battleground objective, accounting for specific terrain rules like jump-downs or cave spawns. It calculates a composite score for each path by weighing the proximity of waypoints to the bot against their distance from the destination, adjusting these weights dynamically according to the battleground type (e.g., IC, AV, WS). The function ultimately returns true if a valid path is found and executed via moveToObjectiveWp, or false otherwise.",
  "params": [
    {
      "name": "vPaths",
      "desc": "A constant reference to a vector containing pointers to BattleBotPath objects representing candidate routes."
    }
  ],
  "returns": "bool",
  "side_effects": "Network (potentially via moveToObjectiveWp), Global State (modifies bot position if successful)",
  "notes": "The function relies on context variables for PositionMap and battleground type; it handles specific edge cases for IC, AV, WS, and EY battlegrounds by adjusting distance scoring multipliers. If no suitable path is found after filtering out paths with disallowed reverse segments or those exceeding the bot's distance limit, it returns false."
}

{
  "summary": "Moves the bot to a waypoint within its current path with randomized offset and handles combat or capture flag conditions.",
  "overview": "This function attempts to move the battle bot toward an objective waypoint by calculating a target point based on the current position in the path. It first validates that the bot is alive, not in a state where it must stop (such as capturing a flag), and has reached the last waypoint if moving forward. The logic supports both normal progression and reverse movement along the path.",
  "params": [
    {
      "name": "currentPath",
      "desc": "Pointer to the battle bot's current path containing waypoints."
    },
    {
      "name": "currentPoint",
      "desc": "The index of the waypoint currently being processed in the path."
    },
    {
      "name": "reverse",
      "desc": "Boolean flag indicating whether to move backward through the path instead of forward."
    }
  ],
  "returns": "bool",
  "side_effects": "Network (MoveTo), Global State (resetObjective)",
  "notes": "Returns false if the bot is dead, not capturing a flag while in combat, or has reached the end of the path. Randomizes the target waypoint by up to 5 steps forward or backward."
}

{
  "summary": "Determines if a battle bot can start moving toward its objective by validating path availability and distance constraints.",
  "overview": "This function checks whether the bot is within range of the objective position and evaluates a list of provided paths to identify valid starting points. It filters out paths that are too close to the objective or restricted from being traversed in reverse, then randomly selects an available path to initiate movement toward the goal.",
  "params": [
    {
      "name": "vPaths",
      "desc": "A constant reference to a vector containing pointers to BattleBotPath objects representing potential routes for the bot."
    }
  ],
  "returns": "bool",
  "side_effects": "None",
  "notes": "The function relies on context data for objective position and internal lists like vPaths_NoReverseAllowed; it may return false if no valid path is found or distance thresholds are not met."
}

{
  "summary": "Determines if a bot can start a new path to the objective by checking distance constraints and selecting the nearest available waypoint.",
  "overview": "This function validates whether a battlebot is eligible to initiate movement toward its objective based on proximity rules and path availability. It first verifies that the battleground exists and is not an Ice Cave type, then checks if the bot is within 25 units of the objective position. If valid, it iterates through the provided vector of paths to identify the closest waypoint relative to the bot's current location.",
  "params": [
    {
      "name": "vPaths",
      "desc": "A constant reference to a vector containing pointers to BattleBotPath objects representing available routes."
    }
  ],
  "returns": "bool",
  "side_effects": "None",
  "notes": "The function relies on the bot's distance calculation and context position data; it returns false if no valid path is found or if the bot is too close to the objective."
}

{
  "summary": "Determines whether a battle bot is currently occupying or attacking a specific flag object based on proximity, state, and team conditions.",
  "overview": "This function evaluates the bot's position relative to game objects matching provided flag IDs within a calculated range. It first checks for enemy players nearby to determine if the bot should retreat from an objective, then verifies if friendly units are capturing the flag to decide whether to move toward it. Finally, it iterates through valid target flags to confirm occupancy or attack status.",
  "params": [
    {
      "name": "vPaths",
      "desc": "A vector of BattleBotPath pointers representing potential movement paths for the bot."
    },
    {
      "name": "vFlagIds",
      "desc": "A vector of unique flag IDs (uint32) that the function should consider as valid targets."
    }
  ],
  "returns": "bool",
  "side_effects": "Network, global state",
  "notes": "Calls MoveTo() to reposition the bot if a friendly unit is capturing the flag; modifies context target and resets objectives. Edge case: returns false if no valid flags are found or if an enemy player is detected within range."
}

{
  "summary": "Returns the count of alive players within a specified distance on the battleground map, filtering by team affiliation and combat status.",
  "overview": "This function queries the current battleground state to identify active players located near a specific coordinate. It first verifies that the bot is currently inside a battleground before proceeding with the search. The iteration checks each player's liveness, team alignment, and whether they are engaged in combat based on the provided flags.",
