      "desc": "The team identifier to filter players; accepts TEAM_NEUTRAL or a specific team ID."
    },
    {
      "name": "point",
      "desc": "A Position struct containing the X and Y coordinates defining the center of the search area."
    },
    {
      "name": "range",
      "desc": "The maximum distance in units from the point within which players are counted."
    },
    {
      "name": "combat",
      "desc": "A boolean flag; if true, excludes players currently engaged in combat from the count."
    }
  ],
  "returns": "uint32",
  "side_effects": "None",
  "notes": "Returns 0 if the bot is not in a battleground or if the battleground map is null. The function relies on server-side distance calculations via sServerFacade and assumes players are stored in bg->GetBgMap()->GetPlayers()."
