{
  "summary": "Moves a bot to a specific coordinate within the battle ground based on its class and the battle ground's layout.",
  "overview": "This function calculates a target position for a bot by first determining a preference value derived from the bot's class, then selecting a coordinate set based on the current battle ground type and team start position. It utilizes the MoveTo helper to relocate the bot to one of several predefined locations within the arena.",
  "params": [
    {
      "name": "bg",
      "desc": "Pointer to the Battleground object containing map ID, team start positions, and battle ground type information."
    }
  ],
  "returns": "bool",
  "side_effects": "Network (MoveTo), Global State (bot movement)",
  "notes": "Calls MoveTo helper; handles DS battle ground with fallback teleportation logic if initial move fails."
}

