  "overview": "This utility function locates the final occurrence of a specified separator within a text string, commonly used to parse delimited data. It specifically handles game-specific formatting by skipping separators that appear inside link tags (e.g., |H...|h|r), ensuring that internal delimiters do not interfere with parsing the outer structure. The implementation uses multiple `rfind` and `find` operations to identify these regions and adjust the result accordingly.",
  "params": [
    {
      "name": "text",
      "desc": "The input string containing potential separators."
    },
    {
      "name": "sep",
      "desc": "The character or string sequence to search for as a separator."
    }
  ],
  "returns": "size_t",
  "side_effects": "None",
