}

{
  "summary": "Removes leading whitespace characters from the beginning of a string in-place.",
  "overview": "This static inline function trims any leading spaces, tabs, or other whitespace characters from the start of a std::string reference. It utilizes std::find_if to locate the first non-whitespace character and then erases all preceding elements up to that point, modifying the original string directly without creating a copy.",
  "params": [
    {
      "name": "s",
      "desc": "A reference to a std::string whose leading whitespace will be removed."
