{
  "summary": "Executes a chat modification action by parsing the incoming event text, updating the current chat state if it's not a system message, and notifying the master AI of the result.",
  "overview": "This function processes an Event object containing chat text to either update the active chat configuration or report the current state. It first extracts the text parameter from the event, parses it into a ChatMsg structure, and checks if the parsed message is a system command. Depending on the message type, it either sets the new chat value in the context or formats and logs the existing chat to the master AI.",
  "params": [
    {
      "name": "event",
      "desc": "The Event object containing the action parameters, specifically the text string to be processed."
    }
  ],
  "returns": "bool",
  "side_effects": "I/O (writes to botAI->TellMaster), global state (modifies context->GetValue<ChatMsg>('chat') if not a system message)",
  "notes": "Always returns true; callers should expect the chat state to be updated or the master AI to receive a status update."
}

